    signalerAnomalie("ANO-UI-02", `DEFECT HIGH — Seulement ${$lines.length} ligne(s) trouvée(s) au lieu de 2 minimum`, "Attendu : ≥2 lignes | Observé : " + $lines.length);
  }
  cy.log(`✅ ÉTAPE 4 — ${$lines.length} ligne(s) trouvée(s)`);
});
// ÉTAPE 5 : Supprimer toutes les lignes
const supprimerTout = () => {
  cy.get("body").then($body => {
    if ($body.find("[data-cy='cart-line-delete']").length > 0) {
      cy.get("[data-cy='cart-line-delete']").first().click();
      cy.wait(600);
      supprimerTout();
    }
  });
};
supprimerTout();
